contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 newItemDailyAllowance, uint256 offset) public payable {
        require(offset < 100);

        uint16 dailyAllowance = uint16(newItemDailyAllowance);

        uint256 countBefore = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;

        c.createGameItem(
            "Test Item",
            "ipfs://test",
            false,
            true,
            0,
            1,
            dailyAllowance
        ); if (__ESBMC_reverted()) return;

        uint256 countAfter = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;
        uint256 tokenId = countBefore;
        uint256 remaining = c.getAllowanceRemaining(address(this), tokenId); if (__ESBMC_reverted()) return;

        assert(countAfter == countBefore + 1 && remaining == dailyAllowance);
    }

    receive() external payable {}
}

