// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(uint256 newItemDailyAllowance, uint256 offset) internal {
        offset = bound(offset, 0, 99);
        uint16 dailyAllowance = uint16(newItemDailyAllowance);
        uint256 countBefore;
        try c.uniqueTokensOutstanding() returns (uint256 __r) { countBefore = __r; } catch { return; }
        try c.createGameItem(
            "Test Item",
            "ipfs://test",
            false,
            true,
            0,
            1,
            dailyAllowance
        ) {} catch { return; }
        uint256 countAfter;
        try c.uniqueTokensOutstanding() returns (uint256 __r) { countAfter = __r; } catch { return; }
        uint256 tokenId = countBefore;
        uint256 remaining;
        try c.getAllowanceRemaining(address(this), tokenId) returns (uint256 __r) { remaining = __r; } catch { return; }
        assertTrue(countAfter == countBefore + 1 && remaining == dailyAllowance);
    }

    function testFuzz_run(uint256 newItemDailyAllowance, uint256 offset) public {
        _run(newItemDailyAllowance, offset);
    }

    receive() external payable {}
}
